}

.lifecycle-icon svg {
  width: 28px;
  height: 28px;
  color: var(--green);
}

.lifecycle-label {
  font-size: 0.875rem;
  font-weight: 500;
}

.lifecycle-arrow {
  color: var(--text-muted);
  font-size: 1.5rem;
}

/* Security features grid */
.security-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
