  margin-bottom: var(--space-2xl);
}

.footer-brand {
  max-width: 280px;
}

.footer-logo {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
}

.footer-logo span {
  color: var(--green);
}

.footer-tagline {
  color: var(--text-secondary);
  line-height: 1.7;
}

.footer-title {
  font-weight: 600;
  margin-bottom: var(--space-lg);
  color: var(--text-primary);
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: var(--space-sm);
}

.footer-links a {
  color: var(--text-secondary);
  transition: var(--transition-fast);
}

.footer-links a:hover {
  color: var(--accent);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
