  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  position: relative;
  z-index: 2;
}

.ecosystem-center-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.ecosystem-center-text {
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.ecosystem-pillar {
