  align-items: center;
  justify-content: center;
  gap: var(--space-md);
  flex-wrap: wrap;
  padding: var(--space-xl);
}

.lifecycle-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.lifecycle-icon {
  width: 64px;
  height: 64px;
  background: var(--bg-card);
  border: 2px solid var(--green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-sm);
}

.lifecycle-icon svg {
  width: 28px;
  height: 28px;
  color: var(--green);
}

.lifecycle-label {
  font-size: 0.875rem;
  font-weight: 500;
}

.lifecycle-arrow {
  color: var(--text-muted);
  font-size: 1.5rem;
}

/* Security features grid */
.security-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-lg);
}

.security-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  transition: var(--transition-base);
}

.security-card:hover {
  border-color: var(--green);
}

.security-card-icon {
  width: 48px;
  height: 48px;
  background: rgba(108, 194, 74, 0.1);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.security-card-icon svg {
  width: 24px;
  height: 24px;
  color: var(--green);
}

.security-card-title {
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.security-card-text {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* Responsive */
@media (max-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
